ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete\s+shadows/i)
  OR (ImageFileName=/\\wbadmin\.exe$/i AND CommandLine=/\bdelete\b/i)
  OR (ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/(bootstatuspolicy\s+ignoreallfailures|recoveryenabled\s+no)/i)
  OR (ImageFileName=/\\wevtutil\.exe$/i AND CommandLine=/\bcl\b/i)
  OR (ImageFileName=/\\fsutil\.exe$/i AND CommandLine=/usn\s+deletejournal/i)
| NOT UserName=/\$$/
| case {
    ImageFileName=/vssadmin/i | Technique := "shadow_delete" ;
    ImageFileName=/wbadmin/i  | Technique := "wbadmin_delete" ;
    ImageFileName=/bcdedit/i  | Technique := "bcdedit_recovery" ;
    ImageFileName=/wevtutil/i | Technique := "evtlog_clear" ;
    ImageFileName=/fsutil/i   | Technique := "usn_delete" ;
    * }
| groupBy([aid, ComputerName, UserName], function=[count(field=Technique, distinct=true, as=TechniqueCount), collect([Technique, ImageFileName, CommandLine, ParentBaseFileName])])
| TechniqueCount >= 2
